1	/**
2	 * @module features/tv-dashboard/ui/TvReportModal
3	 *
4	 * Modal do RELATÓRIO MATINAL (R6): escolhe o dia-base (default ontem),
5	 * mostra o preview do texto pronto (formato WhatsApp) e oferece
6	 * "Copiar" (clipboard) + "WhatsApp" (wa.me). Sem polling — snapshot
7	 * sob demanda via `useTvReport` (habilitado só com o modal aberto).
8	 */
9	
10	import { useState } from 'react';
11	import { Copy, FileText, MessageCircle } from 'lucide-react';
12	import { toast } from 'sonner';
13	import { Button } from '@/shared/ui/button';
14	import {
15	  Dialog,
16	  DialogContent,
17	  DialogDescription,
18	  DialogFooter,
19	  DialogHeader,
20	  DialogTitle,
21	} from '@/shared/ui/dialog';
22	import { Input } from '@/shared/ui/input';
23	import { addDays, toIsoDateLocal } from '../model/tvMath';
24	import { buildTvReportText, useTvReport } from '../model/useTvReport';
25	
26	interface TvReportModalProps {
27	  open: boolean;
28	  onOpenChange: (open: boolean) => void;
29	}
30	
31	/** Modal do relatório diário do Painel TV (copiar/compartilhar). */
32	export function TvReportModal({ open, onOpenChange }: TvReportModalProps) {
33	  // Dia-base default/máximo = ontem (relatório matinal fala do dia fechado)
34	  const yesterday = toIsoDateLocal(addDays(new Date(), -1));
35	  const [baseDate, setBaseDate] = useState(yesterday);
36	
37	  const reportQuery = useTvReport(baseDate, open);
38	  const text = reportQuery.data ? buildTvReportText(reportQuery.data) : null;
39	
40	  const handleCopy = async () => {
41	    if (!text) return;
42	    try {
43	      await navigator.clipboard.writeText(text);
44	      toast.success('Relatório copiado');
45	    } catch {
46	      toast.error('Não foi possível copiar', {
47	        description: 'Selecione o texto do preview e copie manualmente.',
48	      });
49	    }
50	  };
51	
52	  const handleWhatsApp = () => {
53	    if (!text) return;
54	    window.open(
55	      `https://wa.me/?text=${encodeURIComponent(text)}`,
56	      '_blank',
57	      'noopener,noreferrer',
58	    );
59	  };
60	
61	  return (
62	    <Dialog open={open} onOpenChange={onOpenChange}>
63	      <DialogContent
64	        className="max-w-lg border-white/40 bg-white/80 backdrop-blur-xl dark:border-white/10 dark:bg-black/60 sm:rounded-2xl"
65	        data-testid="tv-report-modal"
66	      >
67	        <DialogHeader>
68	          <DialogTitle className="flex items-center gap-2 font-momma text-[#2D362E] dark:text-[#E6DCCF]">
69	            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-2xl bg-[#57715B]/10">
70	              <FileText className="h-4 w-4 text-[#57715B] dark:text-[#8FAE94]" aria-hidden />
71	            </span>
72	            Relatório diário
73	          </DialogTitle>
74	          <DialogDescription>
75	            Texto pronto para enviar aos sócios — faturamento do dia, acumulado
76	            do mês, meta e projeção.
77	          </DialogDescription>
78	        </DialogHeader>
79	
80	        <div className="space-y-3">
81	          <label className="flex flex-wrap items-center gap-2 text-sm font-medium text-[#5F6F63]">
82	            Data-base
83	            <Input
84	              type="date"
85	              value={baseDate}
86	              max={yesterday}
87	              onChange={(e) => {
88	                if (e.target.value) setBaseDate(e.target.value);
89	              }}
90	              className="w-auto rounded-xl border-[#57715B]/15 bg-white/70 tabular-nums focus-visible:ring-[#57715B]/30 dark:bg-black/20"
91	              aria-label="Data-base do relatório"
92	              data-testid="tv-report-date"
93	            />
94	          </label>
95	
96	          <div className="max-h-[50vh] overflow-y-auto rounded-2xl border border-white/20 bg-white/40 p-4 shadow-sm backdrop-blur-md dark:border-white/10 dark:bg-black/20">
97	            {reportQuery.isLoading ? (
98	              <div className="space-y-2 animate-pulse" aria-label="Gerando relatório">
99	                <div className="h-3 w-2/3 rounded-full bg-[#57715B]/10" />
100	                <div className="h-3 w-1/2 rounded-full bg-[#57715B]/10" />
101	                <div className="h-3 w-3/4 rounded-full bg-[#57715B]/10" />
102	                <div className="h-3 w-2/5 rounded-full bg-[#57715B]/10" />
103	              </div>
104	            ) : reportQuery.isError ? (
105	              <p className="text-sm text-amber-600">
106	                Não foi possível gerar o relatório. Tente novamente em instantes.
107	              </p>
108	            ) : (
109	              <pre
110	                className="whitespace-pre-wrap break-words font-mono text-xs leading-relaxed text-[#2D362E] tabular-nums dark:text-[#E6DCCF]"
111	                data-testid="tv-report-preview"
112	              >
113	                {text}
114	              </pre>
115	            )}
116	          </div>
117	        </div>
118	
119	        <DialogFooter className="gap-2 sm:gap-2">
120	          <Button
121	            type="button"
122	            variant="outline"
123	            onClick={handleCopy}
124	            disabled={!text}
125	            data-mia-action="copiar-relatorio-painel-tv"
126	            className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 dark:text-[#8FAE94]"
127	          >
128	            <Copy className="mr-2 h-4 w-4" aria-hidden />
129	            Copiar
130	          </Button>
131	          <Button
132	            type="button"
133	            onClick={handleWhatsApp}
134	            disabled={!text}
135	            data-mia-action="compartilhar-relatorio-whatsapp"
136	            className="rounded-full bg-[#57715B] text-white shadow-lg shadow-[#57715B]/20 hover:bg-[#465b49]"
137	          >
138	            <MessageCircle className="mr-2 h-4 w-4" aria-hidden />
139	            WhatsApp
140	          </Button>
141	        </DialogFooter>
142	      </DialogContent>
143	    </Dialog>
144	  );
145	}
